import useFetch from './hooks/useFetch.js';
import { useState } from 'react';

function Quotes () {

   const url = 'https://zenquotes.io/api/today';

   const [quote, setQuote] = useState('');

    const { data, isPending, error }  = awaiuseFetch(url);

    if (isPending) {
        return (
            <div className="width-fit bg-white-opacity-30">
                <p className="text-white">Loading quote...</p>
            </div>
        )
    }

    if (error) {
        return (
            <div className="width-fit bg-white-opacity-30">
                <p className="text-white">Failed to fetch quote</p>
            </div>
        )
    }

    if (data) {
        setQuote(JSON.stringify(data[0].h));
    }

    return (
        <div className="width-fit bg-white-opacity-30">
            <p>{quote}</p>
        </div>
    )
}

export default Quotes
